const q=kq.l[kq.i],t=q.t;let h='<div class="card q"><div class="row" style="justify-content:space-between;margin:0"><span class="mu">Soal '+(kq.i+1)+' dari '+kq.l.length+'</span><span class="mu">Benar '+kq.ok+'</span></div><div class="bar"><i style="width:'+Math.round(kq.i/kq.l.length*100)+'%"></i></div>';
