const KON=['','いち','に','さん','よん','ご','ろく','なな','はち','きゅう'];
function kAge(n){n=+n;if(!(n>=15&&n<=70))return'○○';const t=Math.floor(n/10),o=n%10;let s='';if(t)s+=(t>1?KON[t]:'')+'じゅう';if(o)s+=KON[o];if(o===0)s=s.replace(/じゅう$/,'じゅっ');if(o===1)s=s.replace(/いち$/,'いっ');if(o===8)s=s.replace(/はち$/,'はっ');return s+'さい'}
